// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading
const { fontFamily: playfairFamily } = loadPlayfair();



export type ChessGraphicProps = Record<string, any>;

// --- SVG Piece Components ---

const PawnSVG = ({ color }: { color: string }) => (
  <svg viewBox="0 0 100 150" width="100%" height="100%">
    {/* Base */}
    <path d="M 20 140 L 80 140 L 70 120 L 30 120 Z" fill={color} />
    {/* Collar/Body */}
    <path d="M 35 120 L 65 120 C 65 80 55 70 55 60 L 45 60 C 45 70 35 80 35 120 Z" fill={color} />
    <rect x="35" y="55" width="30" height="8" rx="4" fill={color} />
    {/* Head */}
    <circle cx="50" cy="40" r="18" fill={color} />
  </svg>
);

const KingSVG = ({ color }: { color: string }) => (
  <svg viewBox="0 0 100 150" width="100%" height="100%">
    {/* Base */}
    <path d="M 15 140 L 85 140 L 75 120 L 25 120 Z" fill={color} />
    {/* Body */}
    <path d="M 30 120 L 70 120 L 65 60 L 35 60 Z" fill={color} />
    <rect x="25" y="55" width="50" height="8" rx="4" fill={color} />
    {/* Crown Base */}
    <path d="M 30 55 L 70 55 L 75 30 L 25 30 Z" fill={color} />
    {/* Cross */}
    <path d="M 45 10 h10 v10 h10 v10 h-10 v10 h-10 v-10 h-10 v-10 h10 z" fill={color} />
  </svg>
);

const QueenSVG = ({ color }: { color: string }) => (
  <svg viewBox="0 0 100 150" width="100%" height="100%">
    {/* Base */}
    <path d="M 15 140 L 85 140 L 75 120 L 25 120 Z" fill={color} />
    {/* Body */}
    <path d="M 30 120 L 70 120 L 60 70 L 40 70 Z" fill={color} />
    <rect x="30" y="65" width="40" height="8" rx="4" fill={color} />
    {/* Crown Points */}
    <path d="M 25 65 L 15 30 L 35 45 L 50 25 L 65 45 L 85 30 L 75 65 Z" fill={color} />
    {/* Crown Jewels */}
    <circle cx="15" cy="25" r="5" fill={color} />
    <circle cx="50" cy="20" r="5" fill={color} />
    <circle cx="85" cy="25" r="5" fill={color} />
  </svg>
);


const ChessGraphic: React.FC<ChessGraphicProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 6,
  boardColorLight = "#f0d9b5",
  boardColorDark = "#b58863",
  pawnColor = "#ffffff",
  kingColor = "#1a1a1a",
  queenColor = "#1a1a1a",
  graphicScale = 1.2,
  labelText = "Strategic Moves",
  labelColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Layout & Grid Settings ---
  // Using a 3x3 grid
  const gridSize = 3;
  const tileHalfW = 70 * graphicScale;
  const tileHalfH = 35 * graphicScale;
  const tileThickness = 15 * graphicScale;

  // Function to map grid coordinates to isometric screen coordinates
  const getScreenPos = (gx: number, gy: number) => ({
    x: (gx - gy) * tileHalfW,
    y: (gx + gy) * tileHalfH,
  });

  // Calculate the visual center of the board to perfectly center it on screen
  const centerPos = getScreenPos(1, 1);
  const boardOffsetX = width / 2 - centerPos.x;
  const boardOffsetY = height / 2 - centerPos.y;

  // --- Animation Timings ---
  const pawnAppearFrame = 40;
  const kingAppearFrame = 70;
  const queenAppearFrame = 90;
  const labelAppearFrame = 110;

  // --- Data Structures for Rendering ---
  // To render 3D/Isometric elements correctly without overlap issues, 
  // we must sort them by depth. Depth in this projection is (gx + gy).
  
  type RenderItem = {
    id: string;
    type: "tile" | "pawn" | "king" | "queen";
    gx: number;
    gy: number;
    depth: number;
    color: string;
    delay: number;
  };

  const renderList: RenderItem[] = [];

  // Generate Tiles
  for (let x = 0; x < gridSize; x++) {
    for (let y = 0; y < gridSize; y++) {
      const isLight = (x + y) % 2 === 0;
      renderList.push({
        id: `tile-${x}-${y}`,
        type: "tile",
        gx: x,
        gy: y,
        depth: x + y,
        color: isLight ? boardColorLight : boardColorDark,
        delay: (x + y) * 5, // Staggered appearance based on depth
      });
    }
  }

  // Generate Pieces
  // Positioning: Pawn in front (center), King & Queen behind it.
  // Pawn at (1,1) (depth 2)
  // King at (0,1) (depth 1) -> Behind pawn
  // Queen at (1,0) (depth 1) -> Behind pawn
  renderList.push({ id: "pawn", type: "pawn", gx: 1, gy: 1, depth: 2, color: pawnColor, delay: pawnAppearFrame });
  renderList.push({ id: "king", type: "king", gx: 0, gy: 1, depth: 1, color: kingColor, delay: kingAppearFrame });
  renderList.push({ id: "queen", type: "queen", gx: 1, gy: 0, depth: 1, color: queenColor, delay: queenAppearFrame });

  // Sort unified list: Tiles render first at the same depth, then pieces.
  renderList.sort((a, b) => {
    if (a.depth === b.depth) {
      return a.type === "tile" ? -1 : 1;
    }
    return a.depth - b.depth;
  });

  // --- Text Label Animation ---
  const labelProgress = spring({
    frame: frame - labelAppearFrame,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  const labelOpacity = interpolate(labelProgress, [0, 1], [0, 1]);
  const labelTranslateY = interpolate(labelProgress, [0, 1], [20, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          left: boardOffsetX,
          top: boardOffsetY,
          width: 0,
          height: 0,
        }}
      >
        {renderList.map((item) => {
          const { x, y } = getScreenPos(item.gx, item.gy);

          if (item.type === "tile") {
            // Tile Animation
            const tileSpring = spring({
              frame: frame - item.delay,
              fps,
              config: { damping: 12, stiffness: 120 },
            });
            const tileScale = interpolate(tileSpring, [0, 1], [0, 1]);

            return (
              <svg
                key={item.id}
                style={{
                  position: "absolute",
                  left: x,
                  top: y,
                  overflow: "visible",
                  transform: `scale(${tileScale})`,
                  transition: "none",
                }}
              >
                {/* Left Face */}
                <polygon
                  points={`-${tileHalfW},0 0,${tileHalfH} 0,${tileHalfH + tileThickness} -${tileHalfW},${tileThickness}`}
                  fill={item.color}
                />
                <polygon
                  points={`-${tileHalfW},0 0,${tileHalfH} 0,${tileHalfH + tileThickness} -${tileHalfW},${tileThickness}`}
                  fill="#000"
                  opacity={0.15}
                />

                {/* Right Face */}
                <polygon
                  points={`${tileHalfW},0 0,${tileHalfH} 0,${tileHalfH + tileThickness} ${tileHalfW},${tileThickness}`}
                  fill={item.color}
                />
                <polygon
                  points={`${tileHalfW},0 0,${tileHalfH} 0,${tileHalfH + tileThickness} ${tileHalfW},${tileThickness}`}
                  fill="#000"
                  opacity={0.3}
                />

                {/* Top Face */}
                <polygon
                  points={`0,-${tileHalfH} ${tileHalfW},0 0,${tileHalfH} -${tileHalfW},0`}
                  fill={item.color}
                />
              </svg>
            );
          }

          // Piece Animation
          const pieceSpring = spring({
            frame: frame - item.delay,
            fps,
            config: { damping: 12, stiffness: 150 },
          });

          const pieceScale = interpolate(pieceSpring, [0, 1], [0, 1]);
          // Springing up from slightly below the board surface
          const pieceTranslateY = interpolate(pieceSpring, [0, 1], [40, 0]);
          // Shadow fades in and tightens as piece lands
          const shadowScale = interpolate(pieceSpring, [0, 1], [1.5, 1]);
          const shadowOpacity = interpolate(pieceSpring, [0, 1], [0, 0.4]);

          return (
            <div
              key={item.id}
              style={{
                position: "absolute",
                left: x,
                top: y,
                width: 100 * graphicScale,
                height: 150 * graphicScale,
                // Center the div horizontally on the grid point, and align its bottom to the grid point
                transform: `translate(-50%, -100%)`,
                transition: "none",
              }}
            >
              {/* Drop Shadow base on the tile */}
              <div
                style={{
                  position: "absolute",
                  bottom: -10 * graphicScale,
                  left: "20%",
                  width: "60%",
                  height: 20 * graphicScale,
                  backgroundColor: "#000",
                  borderRadius: "50%",
                  filter: `blur(${5 * graphicScale}px)`,
                  opacity: shadowOpacity,
                  transform: `scale(${shadowScale})`,
                  transition: "none",
                }}
              />
              
              {/* Actual Piece SVG Container */}
              <div
                style={{
                  width: "100%",
                  height: "100%",
                  transform: `scale(${pieceScale}) translateY(${pieceTranslateY}px)`,
                  transformOrigin: "bottom center",
                  transition: "none",
                }}
              >
                {item.type === "pawn" && <PawnSVG color={item.color} />}
                {item.type === "king" && <KingSVG color={item.color} />}
                {item.type === "queen" && <QueenSVG color={item.color} />}
              </div>
            </div>
          );
        })}
      </div>

      {/* Label Text */}
      {labelText && (
        <div
          style={{
            position: "absolute",
            bottom: height * 0.15,
            width: "100%",
            textAlign: "center",
            fontFamily: playfairFamily,
            fontSize: 48,
            fontWeight: 600,
            color: labelColor,
            opacity: labelOpacity,
            transform: `translateY(${labelTranslateY}px)`,
            transition: "none",
          }}
        >
          {labelText}
        </div>
      )}
    </AbsoluteFill>
  );
};

export default ChessGraphic;